(()=>{
 const dict=clinicalUiTranslations;
 const blocked='script,style,textarea,pre,code,[contenteditable],.chat-log,.archive-field,.hx-language';
 const han=/[\u3400-\u9fff]+(?:[，。；：！？、（）“”《》【】·—～\u3400-\u9fff]*[\u3400-\u9fff])?/g;
 const translate=s=>window.clinicalLockedCaseNames?.has(s)?s:(dict[s]||s.replace(han,x=>window.clinicalLockedCaseNames?.has(x)?x:(dict[x]||x)));
 function clean(node){
  if(node.nodeType===3){if(node.parentElement?.closest('.speaker')){const next=translate(node.nodeValue);if(next!==node.nodeValue)node.nodeValue=next;return;}if(node.parentElement?.closest(blocked))return;const s=node.nodeValue;const t=translate(s);if(t!==s)node.nodeValue=t;return;}
  if(node.nodeType!==1&&node.nodeType!==11)return;
  if(node.nodeType===1&&node.shadowRoot)watch(node.shadowRoot);
  if(node.nodeType===1)for(const attr of ['placeholder','title','aria-label'])if(node.nodeType===1&&node.hasAttribute(attr)){const old=node.getAttribute(attr),next=translate(old);if(old!==next)node.setAttribute(attr,next);}
  if(node.nodeType===1&&node.matches(blocked)){if(node.matches('.chat-log'))for(const label of node.querySelectorAll('.speaker'))for(const child of label.childNodes)clean(child);return;}
  if(node.nodeType===1&&node.tagName==='OPTION'&&!node.hasAttribute('value'))node.setAttribute('value',node.value);
  for(const attr of ['placeholder','title','aria-label'])if(node.nodeType===1&&node.hasAttribute(attr)){const s=node.getAttribute(attr),t=translate(s);if(s!==t)node.setAttribute(attr,t);}
  for(const child of node.childNodes)clean(child);
 }
 const watched=new WeakSet();
 function watch(root){if(watched.has(root))return;watched.add(root);clean(root);new MutationObserver(changes=>{for(const c of changes){if(c.type==='characterData')clean(c.target);else for(const n of c.addedNodes)clean(n);}}).observe(root,{childList:true,subtree:true,characterData:true});}
 document.title=translate(document.title);
 for(const name of ['alert','confirm']){const original=window[name].bind(window);window[name]=message=>original(translate(String(message)));}
 watch(document.body);
})();
